$s="13.53.133.248";$p="8089";$u="admin";$pw="Salam necesen@123";$uri="https://$s`:$p/servicesNS/nobody/search/saved/searches";$auth=[System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes("$u`:$pw"));$h=@{Authorization="Basic $auth"};Get-ChildItem "rules\splunk" -Filter "*.yml"|ForEach-Object{$c=Get-Content $_.FullName -Raw;$id=($c|Select-String "id:\s*`"(.*?)`"").Matches.Groups[1].Value;$name=($c|Select-String "name:\s*`"(.*?)`"").Matches.Groups[1].Value;$search=($c|Select-String "search:\s*>\s*([\s\S]*?)(?=`n[a-z]|\Z)").Matches.Groups[1].Value.Trim();$b=@{name="$id - $name";search=$search;is_scheduled="1";cron_schedule="*/5 * * * *"};try{Invoke-RestMethod -Uri $uri -Method Post -Headers$h -Body $b -SkipCertificateCheck;Write-Host "[+] Created: $id" -ForegroundColor Green}catch{try{Invoke-RestMethod -Uri "$uri/$id" -Method Post -Headers $h -Body $b -SkipCertificateCheck;Write-Host "[+] Updated: $id" -ForegroundColor Yellow}catch{Write-Host "[-] Failed: $id" -ForegroundColor Red}}}
